.woocommerce a.remove {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: 1.6em;
	height: 1.6em;
	border-radius: 50%;
	color: #8c8f94 !important;
	background: transparent;
	font-size: 1.25em;
	transition: color .15s, background .15s;
}
.woocommerce a.remove:hover {
	color: #fff !important;
	background: #d63638;
}
